    "artigoNum": 36,
    "diploma": "Código Civil (Lei 10.406/02)",
    "dispositivo": "Art. 36, inciso III",
    "texto": "III – Da Sucessão Definitiva",
    "explicacao": "Disposição específica de Art. 36, inciso III do diploma Código Civil (Lei 10.406/02).",
    "eixo": "Direito Civil",
    "disciplina": "Direito Civil",
