    "artigoNum": 69,
    "diploma": "Código Civil (Lei 10.406/02)",
    "dispositivo": "Art. 69, inciso III",
    "texto": "III – Do Domicílio",
    "explicacao": "Disposição específica de Art. 69, inciso III do diploma Código Civil (Lei 10.406/02).",
    "eixo": "Direito Civil",
    "disciplina": "Direito Civil",
